def main():
    print(f"Loading documents from {DOCS_PATH}...")
    with open(DOCS_PATH, 'r') as f:
        docs = json.load(f)

    mc_docs = [d for d in docs if 'Medi-Cal' in d.get('programs', [])]
    print(f"Total Medi-Cal documents found: {len(mc_docs)}")

    updated_count = 0
    missing_keys = []

    for d in docs:
        if d.get('id') in ENRICHED_MC_SUMMARIES:
            new_summary = ENRICHED_MC_SUMMARIES[d['id']]
            d['summary'] = new_summary
            updated_count += 1

    for d in mc_docs:
        if d['id'] not in ENRICHED_MC_SUMMARIES:
            missing_keys.append(d['id'])

    if missing_keys:
        print(f"WARNING: The following Medi-Cal documents were NOT in ENRICHED_MC_SUMMARIES: {missing_keys}")
    else:
        print("ALL 146 Medi-Cal documents successfully matched and updated!")

    with open(DOCS_PATH, 'w') as f:
        json.dump(docs, f, indent=2)

    print(f"Saved {len(docs)} documents to {DOCS_PATH}. Successfully updated {updated_count} summaries.")

if __name__ == '__main__':
    main()
